import{_ as i,C as a,c as l,o as d,a3 as o,G as s,j as n,a as r}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Custom fields","description":"","frontmatter":{},"headers":[],"relativePath":"master/general-settings/customization/custom-fields.md","filePath":"master/general-settings/customization/custom-fields.md","lastUpdated":1792041590000}'),g={name:"master/general-settings/customization/custom-fields.md"};function h(c,e,u,m,p,f){const t=a("ImagePopup");return d(),l("div",null,[e[0]||(e[0]=o('<h1 id="custom-fields" tabindex="-1">Custom fields <a class="header-anchor" href="#custom-fields" aria-label="Permalink to &quot;Custom fields&quot;">​</a></h1><p>A <strong>custom field</strong> is an extra field that you add to a form, such as a quotation, an employee or a product. Use it to store information that the standard form does not ask for. You create the field once, and it then appears on the chosen form, in its list and on its view page.</p><blockquote><p><strong>In simple words:</strong> A custom field adds your own box to an existing form, so you can keep the extra details your business needs.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Open <code>Settings → Custom Fields</code> to see all custom fields.</p><p>The list shows these columns:</p><ul><li><strong><em>Code:</em></strong> The technical name of the field.</li><li><strong><em>Name:</em></strong> The label users see.</li><li><strong><em>Type:</em></strong> The kind of input, for example <strong>Text Input</strong> or <strong>Select</strong>.</li><li><strong><em>Resource:</em></strong> The form the field belongs to. The class name is shown below it.</li><li><strong><em>Created At:</em></strong> When you created the field. The newest field is first.</li></ul><p>Use the <strong>All</strong> and <strong>Archived</strong> tabs to switch between active and archived fields. Each tab shows a count. You can search by <strong>Code</strong> or <strong>Name</strong>. You can also filter by <strong>Type</strong> and <strong>Resource</strong>.</p><h2 id="create-a-custom-field" tabindex="-1">Create a custom field <a class="header-anchor" href="#create-a-custom-field" aria-label="Permalink to &quot;Create a custom field&quot;">​</a></h2><ol><li>Go to <code>Settings → Custom Fields</code>.</li><li>Click <strong>Create Field</strong>.</li><li>Fill in the form. The left side holds the field details. The right side holds the type and the target form.</li><li>Click <strong>Create</strong>.</li></ol>',10)),s(t,{src:"/images1/general-settings/custom_fields_create.png",alt:"Create Custom Fields form with name, code, type, sort order and resource"}),e[1]||(e[1]=o('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> The label of the field. This is required.</li><li><strong><em>code:</em></strong> The technical name of the field. This is required and must be unique.</li></ul><p>The code must start with a letter or an underscore. It can contain only letters, numbers and underscores. The code also cannot match an existing column of the target form.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><ul><li><strong><em>Type:</em></strong> Choose the kind of input. This is required.</li><li><strong><em>Input Type:</em></strong> Shown only for <strong>Text Input</strong>. Choose <strong>Text</strong>, <strong>Email</strong>, <strong>Numeric</strong>, <strong>Integer</strong>, <strong>Password</strong>, <strong>Telephone</strong>, <strong>URL</strong> or <strong>Color</strong>.</li><li><strong><em>Is Multiselect:</em></strong> Shown only for <strong>Select</strong>. Turn it on to let users pick more than one value.</li><li><strong><em>Sort Order:</em></strong> A whole number. It sets the position of the field among the other custom fields.</li></ul>',5)),s(t,{src:"/images1/general-settings/custom_fields_settings.png",alt:"Settings section with Type, Input Type and Sort Order"}),e[2]||(e[2]=o('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>After you save, you cannot change <strong>Code</strong>, <strong>Type</strong>, <strong>Input Type</strong>, <strong>Plugin</strong> or <strong>Resource</strong>. Choose them with care.</p></div><h3 id="resource" tabindex="-1">Resource <a class="header-anchor" href="#resource" aria-label="Permalink to &quot;Resource&quot;">​</a></h3><p>Choose where the field appears.</p><ul><li><strong><em>Plugin:</em></strong> Choose the app that owns the form. This is required.</li><li><strong><em>Resource:</em></strong> Choose the form. It appears after you choose a plugin. This is required.</li></ul><p>Only forms that support custom fields are listed. Forms of plugins that are not installed or not active are left out.</p>',5)),s(t,{src:"/images1/general-settings/custom_fields_resource.png",alt:"Resource section with Plugin and Resource selected"}),e[3]||(e[3]=n("h3",{id:"options",tabindex:"-1"},[r("Options "),n("a",{class:"header-anchor",href:"#options","aria-label":'Permalink to "Options"'},"​")],-1)),e[4]||(e[4]=n("p",null,[r("This section appears only for the types "),n("strong",null,"Select"),r(", "),n("strong",null,"Checkbox List"),r(" and "),n("strong",null,"Radio"),r(". Click "),n("strong",null,"Add Option"),r(" for each choice, and type its name.")],-1)),s(t,{src:"/images1/general-settings/custom_fields_options.png",alt:"Options section with several options added"}),e[5]||(e[5]=o('<h3 id="form-settings" tabindex="-1">Form Settings <a class="header-anchor" href="#form-settings" aria-label="Permalink to &quot;Form Settings&quot;">​</a></h3><p>Use this section to control how the field behaves on the form. It has two parts.</p><p><strong>Validations</strong> set rules for the value. Click <strong>Add Validation</strong>, then fill in:</p><ul><li><strong><em>Validation:</em></strong> Choose a rule, for example <strong>Required</strong> or <strong>Max Length</strong>. The list depends on the field type.</li><li><strong><em>Field:</em></strong> Shown only for rules that compare with another field.</li><li><strong><em>Value:</em></strong> Shown only for rules that need a value, for example a number or a text.</li></ul><p><strong>Additional Settings</strong> change the look and help text. Click <strong>Add Setting</strong>, then fill in:</p><ul><li><strong><em>Setting:</em></strong> Choose an option, for example <strong>Default Value</strong>, <strong>Placeholder</strong>, <strong>Helper Text</strong>, <strong>Hint</strong> or <strong>Read Only</strong>. The list depends on the field type.</li><li><strong><em>Value:</em></strong> Enter the value for that setting. Some settings show a <strong>Color</strong> list instead.</li></ul>',6)),s(t,{src:"/images1/general-settings/custom_fields_form_settings.png",alt:"Form Settings section with one validation and one additional setting"}),e[6]||(e[6]=o('<h3 id="table-settings" tabindex="-1">Table Settings <a class="header-anchor" href="#table-settings" aria-label="Permalink to &quot;Table Settings&quot;">​</a></h3><p>Use this section to show the field as a column in the list of the target form.</p><ol><li>Turn on <strong>Use in Table</strong>.</li><li>Click <strong>Add Setting</strong>, if you want to adjust the column.</li><li>Choose a <strong>Setting</strong>, then set its value. Options include <strong>Color</strong>, <strong>Alignment</strong>, <strong>Font Weight</strong>, <strong>Icon Position</strong> and <strong>Size</strong>.</li></ol>',3)),s(t,{src:"/images1/general-settings/custom_fields_table_settings.png",alt:"Table Settings section with Use in Table turned on"}),e[7]||(e[7]=o('<h3 id="infolist-settings" tabindex="-1">Infolist Settings <a class="header-anchor" href="#infolist-settings" aria-label="Permalink to &quot;Infolist Settings&quot;">​</a></h3><p>Use this section to style the field on the read-only view page of a record. Click <strong>Add Setting</strong>, choose a <strong>Setting</strong>, then set its value. Options include <strong>Color</strong>, <strong>Font Weight</strong>, <strong>Icon Position</strong> and <strong>Size</strong>.</p>',2)),s(t,{src:"/images1/general-settings/custom_fields_infolist_settings.png",alt:"Infolist Settings section with one setting added"}),e[8]||(e[8]=o('<h2 id="field-types" tabindex="-1">Field types <a class="header-anchor" href="#field-types" aria-label="Permalink to &quot;Field types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Use it for</th></tr></thead><tbody><tr><td><strong>Text Input</strong></td><td>A single line of text, an email, a number, a phone or a URL</td></tr><tr><td><strong>Textarea</strong></td><td>A longer text</td></tr><tr><td><strong>Select</strong></td><td>A drop-down list with one or more values</td></tr><tr><td><strong>Checkbox</strong></td><td>A yes or no tick box</td></tr><tr><td><strong>Radio</strong></td><td>One choice from a short list</td></tr><tr><td><strong>Toggle</strong></td><td>A yes or no switch</td></tr><tr><td><strong>Checkbox List</strong></td><td>Several choices from a list</td></tr><tr><td><strong>Date Time Picker</strong></td><td>A date, or a date with time</td></tr><tr><td><strong>Rich Text Editor</strong></td><td>Formatted text</td></tr><tr><td><strong>Markdown Editor</strong></td><td>Text written in Markdown</td></tr><tr><td><strong>Color Picker</strong></td><td>A color</td></tr></tbody></table><h2 id="where-custom-fields-appear" tabindex="-1">Where custom fields appear <a class="header-anchor" href="#where-custom-fields-appear" aria-label="Permalink to &quot;Where custom fields appear&quot;">​</a></h2><p>After you save a field, it shows up in these places on the target form:</p><ul><li><strong>Form:</strong> The field appears at the end of the create and edit form.</li><li><strong>List:</strong> The field appears as a column, only when <strong>Use in Table</strong> is on. It is also available in the list filters.</li><li><strong>View page:</strong> The field appears on the read-only page of the record, styled by the <strong>Infolist Settings</strong>.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Saving a new field adds a column to the database table of the target form. So the field is ready to use at once.</p></div><h2 id="edit-archive-and-delete-a-field" tabindex="-1">Edit, archive and delete a field <a class="header-anchor" href="#edit-archive-and-delete-a-field" aria-label="Permalink to &quot;Edit, archive and delete a field&quot;">​</a></h2><p>Click the three dots at the end of a row to open the menu.</p><ul><li><strong><em>Edit:</em></strong> Change the name, options, settings and sort order. You cannot change the locked fields.</li><li><strong><em>Delete:</em></strong> Move the field to the <strong>Archived</strong> tab. Records keep their values.</li><li><strong><em>Restore:</em></strong> Bring an archived field back.</li><li><strong><em>Force delete:</em></strong> Remove the field for good. This also removes its column from the database table.</li></ul><p>You can also select several rows and use the bulk actions for restore, delete and force delete.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Force delete cannot be undone. The values stored in that field are lost.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./sequences.html">Sequences</a></li><li><a href="./../plugins.html">Plugins</a></li><li><a href="./../users/roles.html">Roles</a></li></ul>',13))])}const b=i(g,[["render",h]]);export{_ as __pageData,b as default};
